import boto3
from amazon_transcribe.client import TranscribeStreamingClient

class SpeechClient:
    def __init__(self, region=None):
        self.region = region or boto3.Session().region_name or "us-east-1"
        self.client = TranscribeStreamingClient(region=self.region)

    async def start_transcription_stream(self, language_code, sample_rate_hz, encoding="pcm"):
        return await self.client.start_stream_transcription(
            language_code=language_code,
            media_sample_rate_hz=sample_rate_hz,
            media_encoding=encoding
        )

from dataclasses import dataclass

@dataclass
class TranscriptionResult:
    text: str
    is_final: bool

@dataclass
class AudioChunk:
    content: bytes

import os
from google.cloud import translate_v2 as translate

# Ensure GOOGLE_APPLICATION_CREDENTIALS environment variable is set
# For example: os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = "/path/to/your/keyfile.json"

class LiveCaptionTranslator:
    def __init__(self):
        self.client = translate.Client()

    def translate_caption(self, text, target_language, source_language=None):
        if not text:
            return ""

        result = self.client.translate(text, target_language=target_language, source_language=source_language)
        return result['translatedText']

import os
from google.cloud import language_v1

# Ensure GOOGLE_APPLICATION_CREDENTIALS environment variable is set
# For example: os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = "/path/to/your/keyfile.json"

class LiveCaptionSafetyChecker:
    def __init__(self):
        self.client = language_v1.LanguageServiceClient()

    def check_safety(self, text):
        if not text:
            return {"score": 0.0, "magnitude": 0.0, "is_unsafe": False}

        document = language_v1.Document(content=text, type_=language_v1.Document.Type.PLAIN_TEXT)
        sentiment = self.client.analyze_sentiment(request={'document': document}).document_sentiment

        is_unsafe = False
        # Example heuristic: if sentiment score is very negative and magnitude is high
        if sentiment.score < -0.5 and sentiment.magnitude > 1.0: 
            is_unsafe = True

        return {
            "score": sentiment.score,
            "magnitude": sentiment.magnitude,
            "is_unsafe": is_unsafe
        }
